fn handle_tile_map_pointer(
    ui: &egui::Ui,
    response: &egui::Response,
    loaded: &mut LoadedTileMap,
    layer: &engine_authoring::TileLayerId,
    pointer_cell: Option<engine_authoring::TileCell>,
    tool: TileTool2d,
    fill_bounds: engine_authoring::TileRect,
    work_budget: usize,
) -> Result<(), String> {
    if ui.input(|input| input.key_pressed(egui::Key::Escape)) {
        if loaded.gesture_active {
            loaded.cancel_gesture()?;
        }
        loaded.gesture_start = None;
        return Ok(());
    }

    let result = (|| -> Result<(), String> {
        let Some(cell) = pointer_cell else {
            if response.drag_stopped() {
                if loaded.gesture_active {
                    loaded.cancel_gesture()?;
                }
                loaded.gesture_start = None;
            }
            return Ok(());
        };

        let begin_gesture = |loaded: &mut LoadedTileMap, start| -> Result<(), String> {
            loaded
                .service
                .begin_gesture()
                .map_err(|error| error.to_string())?;
            loaded.gesture_active = true;
            loaded.gesture_start = Some(start);
            Ok(())
        };

        match tool {
            TileTool2d::Paint | TileTool2d::Erase => {
                let tile = matches!(tool, TileTool2d::Paint)
                    .then(|| loaded.selected_tile.clone())
                    .flatten();
                if response.drag_started() {
                    begin_gesture(loaded, cell)?;
                    loaded
                        .service
                        .paint(layer, cell, tile.clone())
                        .map_err(|error| error.to_string())?;
                } else if response.dragged() && loaded.gesture_active {
                    loaded
                        .service
                        .paint(layer, cell, tile.clone())
                        .map_err(|error| error.to_string())?;
                }
                if response.drag_stopped() && loaded.gesture_active {
                    loaded.commit_gesture()?;
                } else if response.clicked() {
                    begin_gesture(loaded, cell)?;
                    loaded
                        .service
                        .paint(layer, cell, tile)
                        .map_err(|error| error.to_string())?;
                    loaded.commit_gesture()?;
                }
            }
            TileTool2d::Rectangle | TileTool2d::Line => {
                let tile = loaded.selected_tile.clone();
                if response.drag_started() {
                    begin_gesture(loaded, cell)?;
                }
                if response.drag_stopped() && loaded.gesture_active {
                    let start = loaded.gesture_start.unwrap_or(cell);
                    match tool {
                        TileTool2d::Rectangle => loaded
                            .service
                            .rectangle(
                                layer,
                                engine_authoring::TileRect::from_corners(start, cell),
                                tile,
                                work_budget,
                            )
                            .map_err(|error| error.to_string())?,
                        TileTool2d::Line => loaded
                            .service
                            .line(layer, start, cell, tile, work_budget)
                            .map_err(|error| error.to_string())?,
                        _ => unreachable!("rectangle/line branch only handles those tools"),
                    }
                    loaded.commit_gesture()?;
                } else if response.clicked() {
                    begin_gesture(loaded, cell)?;
                    loaded
                        .service
                        .paint(layer, cell, tile)
                        .map_err(|error| error.to_string())?;
                    loaded.commit_gesture()?;
                }
            }
            TileTool2d::Fill => {
                if response.clicked() {
                    begin_gesture(loaded, cell)?;
                    loaded
                        .service
                        .fill_bounded(
                            layer,
                            cell,
                            fill_bounds,
                            loaded.selected_tile.clone(),
                            work_budget,
                        )
                        .map_err(|error| error.to_string())?;
                    loaded.commit_gesture()?;
                }
            }
            TileTool2d::Eyedropper => {
                if response.clicked() {
                    loaded.selected_tile = loaded.service.eyedropper(layer, cell);
                }
            }
            TileTool2d::SelectStamp => {
                if loaded.stamp.cells.is_empty() {
                    if response.drag_started() {
                        loaded.gesture_start = Some(cell);
                    }
                    if response.drag_stopped() {
                        let start = loaded.gesture_start.take().unwrap_or(cell);
                        loaded.stamp = loaded.service.copy_stamp(
                            layer,
                            engine_authoring::TileRect::from_corners(start, cell),
                        );
                    } else if response.clicked() {
                        loaded.stamp = loaded.service.copy_stamp(
                            layer,
                            engine_authoring::TileRect::from_corners(cell, cell),
                        );
                    }
                } else if response.clicked() {
                    let stamp = loaded.stamp.clone();
                    begin_gesture(loaded, cell)?;
                    loaded
                        .service
                        .paste_stamp(layer, cell, &stamp, work_budget)
                        .map_err(|error| error.to_string())?;
                    loaded.commit_gesture()?;
                }
            }
        }
        Ok(())
    })();

    if result.is_err() && loaded.gesture_active {
        let _ = loaded.cancel_gesture();
    }
    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn tile_pointer_mapping_preserves_xy_orientation() {
        let rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(250.0, 150.0));
        let cell_size = egui::vec2(10.0, 10.0);
        assert_eq!(
            tile_cell_from_pointer(rect, cell_size, egui::pos2(125.0, 75.0), -12, 7),
            Some(engine_authoring::TileCell { x: 0, y: 0 })
        );
    }

    #[test]
    fn tile_pointer_mapping_rejects_positions_outside_canvas() {
        let rect = egui::Rect::from_min_size(egui::Pos2::ZERO, egui::vec2(250.0, 150.0));
        assert_eq!(
            tile_cell_from_pointer(rect, egui::vec2(10.0, 10.0), egui::pos2(-1.0, 10.0), -12, 7),
            None
        );
    }
}
